using System;
using System.Collections;
using System.IO;
using System.Text;
using UnityEngine;
// Position-controlled integration, not manual or physical driving verification.
public sealed class PassengerCareProbe:MonoBehaviour {
 DriveSession s;int checks;readonly StringBuilder report=new StringBuilder();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Attach(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerCareTest")>=0)new GameObject("Passenger care integration").AddComponent<PassengerCareProbe>();}
 void Check(bool ok,string reason){checks++;report.AppendLine((ok?"PASS ":"FAIL ")+reason);Debug.Log((ok?"PASS ":"FAIL ")+reason);if(!ok)throw new Exception(reason);}
 void Pose(Vector3 point,Vector3 direction){s.taxi.body.position=point+Vector3.up*.65f;s.taxi.body.rotation=Quaternion.LookRotation(direction);s.taxi.transform.SetPositionAndRotation(s.taxi.body.position,s.taxi.body.rotation);Physics.SyncTransforms();}
 void Stop(int index){var p=s.jobs.stops[index];Pose(p.Kerb,p.Direction);}
 void Fresh(){s.business.settings=PrototypeSettings.ForThreeDays();s.business.ledger=new EconomyLedger(s.business.settings);s.business.passengers.Clear();s.business.enabledCampaign=true;s.business.useV2=true;s.business.preparing=false;s.paused=false;Time.timeScale=1;s.jobs.ClearForDay();s.law.ids=new PrototypeIds(Guid.NewGuid().ToString("N"));s.law.ledger=new LawLedger();s.law.tripId="";}
 JobOffer Offer(){return new JobOffer{pickup=0,drop=3,fare=5000,seconds=120,requiredScore=70,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3])};}
 void Board(DrunkRideCase kind){var j=s.jobs;j.ForcedRideCase=kind;var o=Offer();j.offers[0]=o;Stop(o.pickup);Check(j.Accept(0)&&j.trip.State==TripState.ToPickup,"accept "+kind);Check(j.Interact()&&j.trip.State==TripState.OnTrip,"board "+kind);Check(j.StartSatisfaction==o.requiredScore-j.StartDeficit+3,"clean3 baseline once "+kind);var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));Check(saved.version==3&&saved.live!=null&&saved.live.jobs.trip.state==TripState.OnTrip&&saved.live.jobs.drunk.identity==j.DrunkRide.identity,"boarding immediately persists stable active seed "+kind);}
 IEnumerator Start(){yield return new WaitForSecondsRealtime(2);s=FindObjectOfType<DriveSession>();while(!s.StartupReady)yield return null;yield return null;yield return null;if(Array.IndexOf(Environment.GetCommandLineArgs(),"-fuelMenuCapture")>=0){yield return CaptureFuelMenu();Application.Quit(0);yield break;}bool ok=false;try{Run();ok=true;}catch(Exception error){report.AppendLine(error.ToString());Debug.LogException(error);}if(ok&&Array.IndexOf(Environment.GetCommandLineArgs(),"-fareCapture")>=0)yield return CaptureFare();if(ok&&Array.IndexOf(Environment.GetCommandLineArgs(),"-careCapture")>=0)yield return CaptureCare();if(ok&&Array.IndexOf(Environment.GetCommandLineArgs(),"-scoreCapture")>=0)yield return CaptureScores();Directory.CreateDirectory("artifacts");File.WriteAllText("artifacts/passenger-care-integration.txt",report.ToString()+"\nchecks="+checks+"\n");Debug.Log("PASSENGER_CARE_INTEGRATION_"+(ok?"OK":"FAILED")+" checks="+checks);Application.Quit(ok?0:1);}
 IEnumerator CaptureFuelMenu(){
  s.business.enabled=false;s.jobs.enabled=false;s.requests.enabled=false;s.assisted.enabled=false;s.taxi.enabled=false;s.taxi.body.isKinematic=true;s.taxi.body.interpolation=RigidbodyInterpolation.None;
  Fresh();var offer=Offer();s.jobs.offers[0]=offer;Stop(offer.pickup);if(!s.jobs.Accept(0)){Debug.LogError("FUEL_MENU_CAPTURE_FAILED pickup");Application.Quit(1);yield break;}
  var station=s.services.Stations[0];Pose(station.pump,station.direction);s.services.open=true;s.paused=true;Time.timeScale=0;
  foreach(int width in new[]{1280,1920,1280}){Screen.SetResolution(width,width*9/16,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.8f);Pose(station.pump,station.direction);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/fuel-menu-"+width+".png"));yield return new WaitForSecondsRealtime(.5f);}
  Debug.Log("FUEL_MENU_CAPTURE_OK");
 }
 void Run(){s.business.enabled=false;s.jobs.enabled=false;s.jobs.nav.enabled=false;s.requests.enabled=false;s.law.enabled=false;s.manners.enabled=false;s.GetComponent<ServiceLawZones>().enabled=false;s.taxi.enabled=false;s.taxi.body.isKinematic=true;s.taxi.body.interpolation=RigidbodyInterpolation.None;foreach(var c in s.traffic.cars){c.Recycle();c.enabled=false;}
  CheckPickupFuel();CheckDrunkDialogue();CheckWaitingPopulation();
  Fresh();s.jobs.offers[1]=s.jobs.offers[2]=null;var idle=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(s.jobs.CaptureLive()));s.jobs.RestoreLive(idle);Check(s.jobs.trip.State==TripState.Idle&&s.jobs.current==null&&s.jobs.DrunkRide==null&&s.jobs.offers[1]==null&&s.jobs.offers[2]==null,"fresh idle JsonUtility roundtrip preserves nullable passenger and empty offers");
  var first=Offer();s.jobs.offers[0]=first;Stop(first.pickup);Check(s.jobs.Accept(0),"first pickup pre-board snapshot");var pickup=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(s.jobs.CaptureLive()));s.jobs.RestoreLive(pickup);Check(s.jobs.trip.State==TripState.ToPickup&&s.jobs.current!=null&&s.jobs.DrunkRide==null&&s.jobs.RequestReward==null,"first ToPickup JsonUtility roundtrip has no fake drunk/reward");
  foreach(var kind in new[]{DrunkRideCase.Normal,DrunkRideCase.Vomit,DrunkRideCase.Sleepy,DrunkRideCase.Both}){Fresh();Board(kind);var j=s.jobs;bool vomit=kind==DrunkRideCase.Vomit||kind==DrunkRideCase.Both;bool sleepy=kind==DrunkRideCase.Sleepy||kind==DrunkRideCase.Both;j.DrunkRide.Advance(116,.8f);Check(!j.DrunkRide.Vomited,"progress jump warns before actual event "+kind);j.DrunkRide.Advance(3,.8f);j.trip.Tick(119);Check(j.DrunkRide.Vomited==vomit&&j.Cleanliness==100,"vomit waits until disembark "+kind);Stop(j.current.drop);Check(j.Interact(),"first valid arrival "+kind);int expected=j.RequestReward.Total;
   if(sleepy){var arrived=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));Check(arrived.live.jobs.trip.arrivalLocked&&arrived.live.jobs.drunk.Waiting,"first wake attempt immediate checkpoint "+kind);Check(j.Active&&j.DrunkRide.Waiting&&j.trip.Remaining==1,"first arrival freezes deadline "+kind);Check(!s.services.CanUse(4)&&!j.Accept(1),"wake wait blocks services/new calls "+kind);int frozenScore=j.ScoreView.value;s.manners.Deduct("wake-score",2,"기상 대기 후 운전 변화",0);Check(j.ScoreView.value==frozenScore,"waiting HUD keeps frozen arrival score "+kind);var payload=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));string id=s.law.tripId;j.RestoreLive(payload);Check(j.DrunkRide.Waiting&&s.law.tripId==id&&j.RequestReward.Total==expected,"active save roundtrip no reroll "+kind);j.DrunkRide.Advance(14.99f,1);j.Interact();Check(j.Active&&s.business.ledger.Rides==0,"wake before15 rejected "+kind);if(kind==DrunkRideCase.Sleepy){j.DrunkRide.Advance(.01f,1);Check(j.Interact(),"manual wake15");}else{j.DrunkRide.Advance(15.01f,1);Pose(j.stops[j.current.drop].Kerb+Vector3.right*15,j.stops[j.current.drop].Direction);j.SendMessage("UpdateCare");Check(j.Active,"auto30 unsafe location blocked");Stop(j.current.drop);j.SendMessage("UpdateCare");Check(!j.Active,"safe return automatic disembark");}}
   Check(j.trip.State==TripState.Complete&&s.business.ledger.Rides==1&&s.business.passengers.Count==1,"single normal settlement "+kind);Check(j.Cleanliness==(vomit?10:98),"clean result "+kind);Check(s.business.passengers[0].paid==expected&&s.business.passengers[0].vomited==vomit,"result preserves frozen fare/vomit "+kind);Check(j.trip.Complete()==0&&!s.business.ledger.Account.Fare(s.law.tripId,expected,1),"no second fare "+kind);
  }
  Fresh();s.business.ledger.Care.Finish("dirty-precondition",true);var offer=Offer();s.jobs.offers[0]=offer;Stop(offer.pickup);Check(!s.jobs.Accept(0),"vomit blocks dispatch before first roadside refusal");var waiting=s.jobs.CaptureLive();waiting.waitingCaptured=true;waiting.roadsideWaiting=new bool[s.jobs.stops.Length];waiting.roadsideWaiting[0]=waiting.roadsideWaiting[1]=true;waiting.cooldown=new float[s.jobs.stops.Length];s.jobs.RestoreLive(waiting);int cash=s.business.ledger.Account.Cash;Check(!s.jobs.Interact()&&s.jobs.AcceptanceLocked&&s.jobs.trip.State==TripState.Idle&&s.jobs.VisibleCareDialogue.Contains("못 타겠어요"),"dirty roadside approach reaches visible spoken refusal despite dispatch lock");Check(s.law.tripId==""&&s.business.ledger.Account.Cash==cash&&s.business.ledger.Rides==0&&s.business.passengers.Count==0,"refusal no tripID/fare/completion");Stop(1);Check(!s.jobs.Interact()&&s.business.ledger.Care.Refusals==2&&s.jobs.VisibleCareDialogue.Contains("못 타겠어요"),"new roadside candidate repeats spoken refusal until wash");s.jobs.offers[0]=Offer();Check(!s.jobs.Accept(0),"repeat dispatch blocked until wash");
  foreach(var station in s.services.Stations){Pose(station.pump,station.direction);s.services.open=true;double elapsed=s.business.ledger.Elapsed;int cost=s.business.ledger.Account.Expense(1,"wash");Check(s.services.RequestAction(4)&&!s.services.ConfirmAction(false),"wash cancellation "+station.id);Check(s.business.ledger.Elapsed==elapsed&&s.business.ledger.Account.Expense(1,"wash")==cost,"cancel no cost/time "+station.id);Check(s.services.RequestAction(4)&&s.services.ConfirmAction(true),"wash standalone at "+station.id);Check(s.jobs.Cleanliness==100&&!s.jobs.AcceptanceLocked&&s.business.ledger.Elapsed==elapsed+30,"wash30 and unlock "+station.id);}
  Fresh();Board(DrunkRideCase.Sleepy);s.jobs.trip.Tick(121);s.jobs.DrunkRide.Advance(121,.8f);Stop(s.jobs.current.drop);s.jobs.Interact();s.business.ledger.Advance(1201,0);Check(s.business.ledger.Operating&&s.jobs.Active,"overtime cannot remove sleeping passenger");s.jobs.DrunkRide.Advance(15,1);s.jobs.Interact();Check(s.jobs.trip.State==TripState.Failed&&s.business.ledger.Rides==0&&s.business.ledger.FailedTrips==1,"late before arrival stays zero despite wake");
  Fresh();Stop(0);s.jobs.Generate();int ordinary=0;foreach(var o in s.jobs.offers)if(o!=null&&string.IsNullOrEmpty(o.scenarioId)){ordinary++;Check(!string.IsNullOrEmpty(o.pickupStopId)&&!string.IsNullOrEmpty(o.catalogRevision),"ordinary stable catalog IDs");}Check(s.jobs.stops.Length>12&&ordinary>0,"additional stops reach normal call generation");Check(s.GetComponent<ServiceLawZones>().scenarios.Count==9,"nine fixed courses preserved");
  CheckScoreFlow();CheckRecoveryFlow();CheckScenarioRestore();
 }
 void CheckPickupFuel(){
  Fresh();var j=s.jobs;var service=s.services;var offer=Offer();j.offers[0]=offer;Stop(offer.pickup);Check(j.Accept(0),"fuel pickup accepted");string id=j.OfferId;float beforeWait=j.trip.PickupRemaining;
  var pump=service.Stations[0];Pose(pump.pump,pump.direction);service.open=true;
  Check(service.FuelMenuOnly&&service.GuideFuel(0)&&j.Active&&j.OfferId==id&&j.trip.PickupRemaining==beforeWait,"fuel guide keeps pickup identity and clock");service.open=true;
  int cash=s.business.ledger.Account.Cash;float fuel=s.business.ledger.Account.Fuel;double elapsed=s.business.ledger.Elapsed;
  Check(service.Buy(0),"pickup fuel purchase");Check(j.trip.State==TripState.ToPickup&&j.OfferId==id&&j.trip.PickupRemaining==beforeWait-10,"fuel retains call and advances pickup wait10");
  Check(s.business.ledger.Account.Cash==cash-400&&s.business.ledger.Account.Fuel>fuel+9&&s.business.ledger.Elapsed==elapsed+10,"fuel cost volume elapsed");
  var savedFuel=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));Check(savedFuel.live.jobs.trip.state==TripState.ToPickup&&savedFuel.live.jobs.offerId==id,"fuel checkpoint retains accepted call");
  Check(service.RequestAction(4)&&service.ConfirmAction(true),"pickup wash purchase");Check(j.trip.State==TripState.ToPickup&&j.OfferId==id&&j.trip.PickupRemaining==beforeWait-40,"wash retains call and advances pickup wait30");
  Check(j.nav.hdGoal==j.stops[offer.pickup].laneEdge,"service exit resumes pickup navigation");
  Pose(pump.pump,pump.direction);service.open=true;j.trip.Tick(j.trip.PickupRemaining-5);Check(service.Buy(0)&&j.trip.PickupExpired&&!j.Active,"service time can expire pickup honestly");
  service.Toggle();Fresh();
 }
 IEnumerator CaptureCare(){
  s.requests.enabled=true;s.services.open=false;s.GetComponent<RideCompletionPanel>().Close();
  for(int phase=0;phase<3;phase++){
   Fresh();Board(DrunkRideCase.Vomit);var j=s.jobs;
   if(phase<2){j.DrunkRide.Advance(20,1);if(phase==1){j.DrunkRide.Advance(3,1);s.business.ledger.Care.MarkVomit();}}
   else {Fresh();s.business.ledger.Care.Finish("capture-dirty",true);j.offers[0]=Offer();var waiting=j.CaptureLive();waiting.waitingCaptured=true;waiting.roadsideWaiting=new bool[j.stops.Length];waiting.roadsideWaiting[0]=true;j.RestoreLive(waiting);Stop(0);j.Interact();}
   Time.timeScale=0;s.paused=false;
   foreach(int width in new[]{1280,1920}){Screen.SetResolution(width,width*9/16,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/care-"+new[]{"warning","vomit","refusal"}[phase]+"-"+width+".png"));yield return new WaitForSecondsRealtime(.3f);}
  }
  Fresh();var offer=Offer();s.jobs.offers[0]=offer;Stop(offer.pickup);Check(s.jobs.Accept(0),"capture pickup accepted");var station=s.services.Stations[0];Pose(station.pump,station.direction);s.services.open=true;s.paused=true;Time.timeScale=0;
  foreach(int width in new[]{1280,1920}){Screen.SetResolution(width,width*9/16,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/fuel-menu-"+width+".png"));yield return new WaitForSecondsRealtime(.3f);}
  s.services.open=false;s.requests.enabled=false;Time.timeScale=1;
 }
 IEnumerator CaptureFare(){
  Screen.SetResolution(1280,720,FullScreenMode.Windowed);yield return new WaitForSecondsRealtime(.5f);
  foreach(int score in new[]{48,0}){
   var panel=s.GetComponent<RideCompletionPanel>();panel.Close();Fresh();Board(DrunkRideCase.Normal);var j=s.jobs;var state=j.CaptureLive();
   state.initialFare=state.current.fare=state.trip.fare=11300;state.current.requiredScore=60;state.startSatisfaction=score;state.cleanBonus=0;state.startDeficit=60-score;state.referenceSeconds=100;state.request.request.kind=RequestKind.Eta;j.RestoreLive(state);
   Check(j.SettlementPolicyVersion==4,"new fare policy survives live restore");j.DrunkRide.Advance(100,.8f);j.trip.Tick(100);Stop(j.current.drop);Check(j.Interact(),"new policy delivery "+score);
   var result=s.business.passengers[0];Check(result.farePolicyVersion==4&&result.satisfaction==score&&result.paid==(score==48?9040:0)&&result.bonus==0,"shipping settlement correct for satisfaction "+score);
   Check(panel.ShowLast(),"show settled fare receipt "+score);yield return new WaitForSecondsRealtime(.3f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/fare-policy4-"+score+".png"));yield return new WaitForSecondsRealtime(.3f);
  }
 }
 void CheckDrunkDialogue(){
  Fresh();Board(DrunkRideCase.Vomit);var j=s.jobs;var state=j.CaptureLive();state.request.quietReply=true;j.RestoreLive(state);
  j.DrunkRide.Advance(20,0);j.DrunkRide.UpdateDialogue(true);Check(j.VisibleCareDialogue=="","quiet request suppresses ordinary drunk speech in HUD source");
  j.DrunkRide.Advance(0,1);Check(j.VisibleCareDialogue.Contains("토할 것"),"explicit pre-vomit warning visible despite quiet request");
  s.business.SaveCheckpoint();var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));j.RestoreLive(saved.live.jobs);Check(j.VisibleCareDialogue.Contains("토할 것")&&!j.DrunkRide.Advance(2.9f,1),"warning persists in real checkpoint without early event");
  int fare=j.trip.Fare;string id=s.law.tripId;Check(j.DrunkRide.Advance(.11f,1),"actual event follows full warning lead");j.SendMessage("UpdateCare");
  Check(j.VisibleCareDialogue.Contains("구토 발생")&&j.Cleanliness==100&&j.AcceptanceLocked&&j.trip.State==TripState.OnTrip&&j.trip.Fare==fare&&s.law.tripId==id,"critical event visible and dispatch latched without altering occupied fare or early cleanliness");
  s.business.SaveCheckpoint();saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));j.RestoreLive(saved.live.jobs);Check(!j.DrunkRide.Advance(0,1)&&j.AcceptanceLocked,"actual event restore cannot replay and retains lock");
 }
 string Notices(DriveNotifications notifications){return string.Join("\n",notifications.VisibleTexts);}

 void CheckRecoveryFlow(){
  Fresh();Board(DrunkRideCase.Normal);var j=s.jobs;var state=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));state.current.requiredScore=70;state.startSatisfaction=60;state.cleanBonus=0;j.RestoreLive(state);
  var notices=s.GetComponent<DriveNotifications>();notices.RefreshScores();Check(s.manners.Deduct("brake",2,"급제동",0)&&j.ScoreView.value==58,"motion loss lowers live S gauge");
  var p=s.taxi.transform.position;for(int i=0;i<=45;i++)s.manners.ObserveStable(p.x+i,p.z,1,1,true);
  Check(s.manners.ledger.Score==100&&j.ScoreView.value==60&&notices.VisibleText=="안정적인 주행 · +2","stable recovery changes live S gauge and immediate positive notice");
  var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));Check(saved.live.jobs.manners.recoveryCaptured&&saved.live.jobs.manners.stableRecovered==2&&saved.live.jobs.manners.stable!=null,"shipping checkpoint contains recovery progress");
  j.RestoreLive(saved.live.jobs);Check(s.manners.ledger.Score==100&&s.manners.ledger.StableRecovered==2&&j.ScoreView.value==60,"restored recovery cannot double count and retains live S");
  var reward=PassengerReward.CalculateDetailed(s.manners.ledger.Score,70,5000,0,0,true,60,0,0,0,false);Check(reward.baseFare==4750&&reward.bonus==0&&reward.satisfaction==60,"S60 below R70 deducts ten missing satisfaction points despite M100");
  var q=s.taxi.transform.position;for(int i=0;i<=65;i++)s.manners.ObserveStable(q.x,q.z+i,1,1,true);
  Check(j.ComfortRecovered==2&&j.ScoreView.value==62&&notices.VisibleText=="안정 주행 안심 · +2","no M gain awards direct comfort with correct immediate notice");
  saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));j.RestoreLive(saved.live.jobs);
  Check(j.ComfortRecovered==2&&j.BoardingDrivingScore==100&&j.SettlementPolicyVersion==4&&j.DrivingFareCaptured&&j.ScoreView.value==62,"shipping save restores comfort and boarding fare once");
  Check(j.RecoverComfort(2)==0&&j.RecoverComfort(0)==2&&j.RecoverComfort(0)==0&&j.ScoreView.value==64,"M exclusion and four-point trip cap survive restore");
  var legacy=j.CaptureLive();legacy.drivingFareCaptured=false;legacy.comfortRecovered=0;legacy.referenceSeconds=100;legacy.startSatisfaction=60;legacy.request.request.kind=RequestKind.Eta;j.RestoreLive(legacy);
  j.DrunkRide.Advance(100,.8f);j.trip.Tick(100);Stop(j.current.drop);Check(j.Interact()&&j.RequestReward.farePolicyVersion==2&&j.RequestReward.baseFare==4750,"legacy active save settles original unadjusted agreement");
 }

 void CheckScoreFlow(){
  Fresh();var j=s.jobs;var notices=s.GetComponent<DriveNotifications>();notices.RefreshScores();Board(DrunkRideCase.Normal);
  var snapshot=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));snapshot.request.request.kind=RequestKind.Quiet;snapshot.current.requiredScore=85;snapshot.startSatisfaction=76;snapshot.startDeficit=12;snapshot.cleanBonus=3;snapshot.referenceSeconds=100;j.RestoreLive(snapshot);
  notices.RefreshScores();Check(j.ScoreView.value==76&&j.ScoreView.required==85&&s.GetComponent<DriveHUD>().MannerCaption.Contains("76"),"HUD actual S76/R85 rather than M100");Check(notices.VisibleTexts.Length==0,"boarding baseline is not misreported as a score gain");
  Check(s.manners.Deduct("brake-score-test",2,"급제동",0),"actual driving deduction applied");Check(j.ScoreView.value==74&&notices.VisibleText=="급제동 · -2","driving deduction changes gauge and notice immediately before LateUpdate");
  s.requests.request.Accept();s.requests.request.CompleteGoal(true,"actual quiet fulfillment");notices.RefreshScores();Check(j.ScoreView.value==79&&notices.VisibleText=="요청 이행 · +5"&&Notices(notices).Contains("급제동 · -2"),"request fulfillment changes gauge and notification without changing M98");
  var e=new LawEvent{id=s.law.ids.Next("score-test"),day=1,action="신호 위반"};e.Add("signal",LawVerdict.Violation,20);s.law.ledger.Record(e);notices.RefreshScores();Check(s.law.ledger.TotalScore==80&&j.ScoreView.value==79&&notices.VisibleText=="신호 위반 · -20"&&Notices(notices).Contains("요청 이행 · +5"),"actual independent law event updates cumulative gauge/notification only");
  e=new LawEvent{recoveryPolicyVersion=1,id=s.law.ids.Next("score-test"),day=1,action="양보 준수"};e.Add("yield",LawVerdict.Compliant,0);s.law.ledger.Record(e);notices.RefreshScores();Check(s.law.ledger.TotalScore==83&&notices.VisibleText=="양보 준수 · +3"&&notices.VisibleTexts.Length==4,"actual law recovery updates cumulative UI");
  snapshot=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));j.RestoreLive(snapshot);Check(j.ScoreView.value==79&&j.ScoreView.required==85&&s.manners.ledger.Score==98,"live restore preserves displayed passenger values");
  j.DrunkRide.Advance(100,.8f);j.trip.Tick(100);Stop(j.current.drop);Check(j.Interact(),"score regression actual delivery");var result=s.business.passengers[0];notices.RefreshScores();Check(result.satisfaction==79&&result.startSatisfaction==76&&result.cleanBonus==3&&result.driveDelta==-2&&result.satisfactionDelta==5,"receipt actual stored score includes cleanliness once and drive/request changes");Check(j.ScoreView.value==result.satisfaction&&PassengerScoreView.Recorded(result).value==result.satisfaction,"frozen HUD agrees with stored receipt");Check(result.hasDrivingScore&&result.drivingScore==83,"receipt captures actual cumulative law score at delivery");Check(result.initialFare==5000&&result.baseFare==4640&&result.boardingDrivingScore==100&&result.drivingAdjustedFare==5500&&RideReceiptSummary.Money(result).Contains("실수령  4,640원"),"receipt shows six-point satisfaction fare deduction");
  var saved=JsonUtility.FromJson<CampaignCheckpoint>(File.ReadAllText(s.business.SavePath));Check(saved.passengers[0].satisfaction==79&&saved.passengers[0].drivingScore==83&&saved.passengers[0].hasDrivingScore,"shipping JsonUtility checkpoint preserves satisfaction and law result");
  j.PrepareForNextCall();j.offers[0]=Offer();Stop(j.offers[0].pickup);Check(j.Accept(0),"new pickup after completed score");j.trip.Tick(j.trip.PickupRemaining+1);Check(!j.HasPassengerScore,"expired pickup cannot show previous passenger result or a false boarding");notices.RefreshScores();Check(!Notices(notices).Contains("만족도"),"next unboarded pickup removes stale passenger notices");Fresh();Board(DrunkRideCase.Normal);var failedRequest=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(j.CaptureLive()));failedRequest.request.request.kind=RequestKind.Comfort;j.RestoreLive(failedRequest);notices.RefreshScores();s.requests.request.Accept();s.requests.request.CompleteGoal(false,"comfort request not fulfilled");notices.RefreshScores();Check(notices.VisibleText=="요청 미이행 · -10","negative request notice identifies failure rather than fulfillment");
 }
 IEnumerator CaptureScores(){
